    "C18"
  ],
  "contradictory_card_ids": [
    "C207", "C187", "C14", "C43"
  ],
  "prediction_basis_card_ids": [
    "C47", "C51", "C10", "C80",
    "C04", "C08", "C15", "C46",
    "C122", "C133", "C170", "C213"
  ],
  "claims": [
    {
      "claim": "The closest estradiol analogue with the same phenolic A-ring and steroid core, 2-methoxyestradiol, has measured oral F of 1–2% in patients and 3.04% in rats, with no detectable plasma exposure in another rat study; this is the strongest transferable low-F precedent for the estradiol moiety of the query ester.",
      "card_ids": ["C47", "C17", "C29", "C51", "C64"]
    },
    {
      "claim": "Unmodified steroids progesterone and danazol have oral F below 20%: progesterone ~5% to <10% in humans and 4.1±1% in rats; danazol 11–19% in fasted humans and 17±3.4% even with 1000 mL water.",
      "card_ids": ["C10", "C21", "C42", "C80", "C04", "C08", "C15", "C46", "C49", "C93"]
    },
    {
      "claim": "L3 oral exposure records for estradiol itself show low pg/mL Cmax after mg doses (43.66 pg/mL after 2 mg E2/NGM; 13.3 pg/mL unconjugated estradiol after 0.625 mg Cenestin), consistent with extensive first-pass metabolism of the estradiol moiety released from the query ester.",
      "card_ids": ["C122", "C133"]
    },
    {
      "claim": "L4 solubility records show estradiol has very low aqueous solubility (1.81 µg/mL in buffer; 7.3 µM in cell culture medium; 10.4 µM in L-15 medium), and the query's 17-cyclopentanepropionate ester is even more lipophilic (logD 6.13), adding a dissolution barrier.",
      "card_ids": ["C170", "C213", "C196", "C199"]
    },
    {
      "claim": "Steroid permeability is high (testosterone fraction absorbed 100% in humans; Caco-2 Papp for progesterone ~3–5×10^-5 cm/s), so the low F of estradiol-like steroids is not explained by poor membrane permeability but by first-pass metabolism and solubility; high permeability does not rescue the low systemic F.",
      "card_ids": ["C207", "C187", "C174", "C195"]
    },
    {
      "claim": "Ethinyl estradiol high-exposure records (Cmax ~58–124 pg/mL after 0.02–0.035 mg) reflect 17α-ethinyl metabolic protection absent in the query 17-ester, and EMP parent-drug non-detection shows that metabolite-based ~40% values do not support high parent F.",
      "card_ids": ["C131", "C156", "C120", "C129", "C132", "C163", "C18", "C109", "C38"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C170", "C213", "C196", "C199", "C207", "C187", "C174", "C195"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for estradiol cypionate itself is present in the supplied records.",
    "L4 solubility/permeability records are for estradiol, testosterone, and progesterone, not the query ester; no query-specific solubility or permeability measurement.",
    "L3 exposure records lack IV comparators, so they cannot independently quantify F.",
    "Dose, formulation, and prandial state for the query are unspecified; oral F of lipophilic steroids is highly formulation-dependent.",
    "Whether bioavailability should be assessed as parent ester or hydrolyzed estradiol moiety is unresolved.",
    "Ester hydrolysis rate and site, and the resulting first-pass metabolism, are not directly characterized."
  ],
  "decision_summary": "Predicted low and strengthened: L4 confirms estradiol-like steroids have very low aqueous solubility (estradiol 1.81 µg/mL; 7.3 µM) while membrane permeability is high, so the low oral F of the closest analogues (2-methoxyestradiol 1–2%, progesterone ~5%, danazol 11–19%) is not rescued by permeability; the query's more lipophilic 17-cyclopentanepropionate ester adds a dissolution barrier, and the released estradiol moiety is subject to extensive first-pass metabolism. Ethinyl estradiol high-exposure records are not transferable due to 17α-ethinyl protection."
}

